<template>
  <MarketplaceLayout><main class="market-container green-community community-form-page"><RouterLink :to="id?'/community/posts/'+id:'/community'">{{ id?'Quay lại bài viết':'Về cộng đồng' }}</RouterLink><h1>{{ id?'Chỉnh sửa bài viết':'Chia sẻ với góc xanh' }}</h1>
    <ResourceState v-if="loading||loadError" resource="bài viết" :loading="loading" :error="Boolean(loadError)" :error-message="loadError" :not-found="notFound" recovery-to="/community" @retry="load"/>
    <p v-else-if="!canEdit" role="alert">Bạn chỉ có thể chỉnh sửa bài của chính mình khi thảo luận đang mở.</p>
    <form v-else class="community-form" @submit.prevent="save"><p class="community-hint">Chia sẻ điều bạn đã quan sát. Không đăng thông tin riêng tư; nội dung được hiển thị dưới dạng văn bản an toàn.</p>
      <div class="community-form-grid"><div><label for="post-type">Loại bài viết</label><select id="post-type" v-model="form.postType" :disabled="busy||awaitingImages"><option v-for="(label,key) in allowedTypes" :key="key" :value="key">{{ label }}</option></select></div><div><label for="post-topic">Chủ đề</label><select id="post-topic" v-model="form.topic" :disabled="busy||awaitingImages"><option v-for="(label,key) in topics" :key="key" :value="key">{{ label }}</option></select></div></div>
      <div><label for="post-title">Tiêu đề</label><input id="post-title" v-model="form.title" required maxlength="180" :disabled="busy||awaitingImages"/></div>
      <fieldset v-if="form.postType==='PLANT_HELP'"><legend>Thông tin để mọi người giúp cây (tùy chọn)</legend><div class="community-form-grid"><div v-for="([label,max],key) in careFields" :key="key"><label :for="'care-'+key">{{ label }}</label><textarea :id="'care-'+key" v-model="form.care[key]" rows="2" :maxlength="max" :disabled="busy||awaitingImages"/></div></div></fieldset>
      <div><label for="post-body">{{ form.postType==='PLANT_HELP'?'Mô tả tình trạng và câu hỏi':'Nội dung bài viết' }}</label><textarea id="post-body" v-model="form.body" required maxlength="12000" rows="10" :disabled="busy||awaitingImages" aria-describedby="post-body-hint"/><p id="post-body-hint" class="community-hint">Tối đa 12.000 ký tự. Với bài cứu cây, tác giả sẽ tự xác nhận khi vấn đề được giải quyết.</p></div>
      <ul v-if="savedPost?.images?.length" class="community-image-previews"><li v-for="(image,i) in savedPost.images" :key="image.id"><img :src="image.url" :alt="'Ảnh đã lưu '+(i+1)"/><button type="button" class="button button-outline" :disabled="busy||awaitingImages" @click="removeImage(image)">Xóa ảnh {{ i+1 }}</button></li></ul>
      <p v-if="awaitingImages" class="community-hint" role="status">Nội dung bài viết đã được lưu. Hoàn tất hoặc bỏ các ảnh đang chờ trước khi chỉnh sửa nội dung tiếp; thử lại chỉ tải ảnh và không đăng thêm bài.</p><ImagePicker v-model="files" :existing="savedPost?.images?.length||0" :disabled="busy"/>
      <p v-if="error" ref="errorBox" tabindex="-1" role="alert">{{ error }}</p><p v-if="progress" role="status">{{ progress }}</p><div class="community-actions"><button class="button button-primary" :disabled="busy||!form.title.trim()||!form.body.trim()">{{ busy?'Đang lưu…':id||savedPost?'Lưu thay đổi':'Đăng bài viết' }}</button><RouterLink class="button button-outline" :to="savedPost?'/community/posts/'+savedPost.id:id?'/community/posts/'+id:'/community'">{{ savedPost?'Xem bài đã lưu':'Hủy' }}</RouterLink></div>
    </form>
  </main></MarketplaceLayout>
</template>
<script setup>
import {ref,reactive,computed,watch,onBeforeUnmount,nextTick} from 'vue';import {useRoute,useRouter} from 'vue-router';import MarketplaceLayout from '../../../layouts/MarketplaceLayout.vue';import ResourceState from '../../../components/marketplace/ResourceState.vue';import ImagePicker from '../../../components/community/ImagePicker.vue';import {marketplaceRequest as request} from '../../../services/marketplace.js';import {topics} from '../../../services/discussions.js';import {postTypes,careFields,newCare,uploadCommunityImage} from '../../../services/community.js';import {useAuth} from '../../../composables/useAuth.js';import '../../../css/community.css';
const route=useRoute(),router=useRouter(),{user,isAdmin}=useAuth(),id=computed(()=>route.params.id),loading=ref(false),loadError=ref(''),notFound=ref(false),busy=ref(false),awaitingImages=ref(false),error=ref(''),progress=ref(''),errorBox=ref(null),files=ref([]),savedPost=ref(null),form=reactive({title:'',body:'',topic:'CARE',postType:'QUESTION',care:newCare(),revision:0,requestKey:crypto.randomUUID()});let generation=0;
const allowedTypes=computed(()=>Object.fromEntries(Object.entries(postTypes).filter(([k])=>k!=='ANNOUNCEMENT'||isAdmin.value))),canEdit=computed(()=>!savedPost.value||savedPost.value.authorId===user.value?.id&&!savedPost.value.locked);
async function load(){const ticket=++generation;awaitingImages.value=false;loadError.value='';notFound.value=false;error.value='';savedPost.value=null;files.value=[];Object.assign(form,{title:'',body:'',topic:'CARE',postType:isAdmin.value&&route.query.type==='ANNOUNCEMENT'?'ANNOUNCEMENT':'QUESTION',care:newCare(),revision:0,requestKey:crypto.randomUUID()});if(!id.value)return;loading.value=true;try{const post=await request('/community/posts/'+encodeURIComponent(id.value));if(ticket===generation){savedPost.value=post;Object.assign(form,{title:post.title,body:post.body,topic:post.topic,postType:post.postType,care:{...newCare(),...post.care},revision:post.revision});}}catch(e){if(ticket===generation){loadError.value=e.message;notFound.value=e.status===404;}}finally{if(ticket===generation)loading.value=false;}}
async function fail(e){error.value=e.message;await nextTick();errorBox.value?.focus();}
async function save(){if(busy.value)return;busy.value=true;error.value='';const ticket=generation;try{if(!awaitingImages.value){const target=savedPost.value?.id||id.value;const post=await request('/account/community/posts'+(target?'/'+target:''),target?'PUT':'POST',{...form,revision:savedPost.value?.revision??form.revision});if(ticket!==generation)return;savedPost.value=post;awaitingImages.value=files.value.length>0;}for(const file of [...files.value]){progress.value='Bài đã lưu. Đang tải ảnh…';const updated=await uploadCommunityImage(savedPost.value,file);if(ticket!==generation)return;savedPost.value=updated;files.value=files.value.filter(f=>f.key!==file.key);}awaitingImages.value=false;await router.push('/community/posts/'+savedPost.value.id);}catch(e){if(ticket===generation)await fail(e);}finally{busy.value=false;progress.value='';}}
async function removeImage(image){if(busy.value)return;busy.value=true;error.value='';try{savedPost.value=await request('/account/community/posts/'+savedPost.value.id+'/images/'+image.id+'?revision='+savedPost.value.revision,'DELETE');}catch(e){await fail(e);}finally{busy.value=false;}}
watch(()=>id.value,load,{immediate:true});onBeforeUnmount(()=>generation++);
watch(()=>user.value?.id,load);
</script>
